use vstd::prelude::*;

verus! {
    fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
        ensures
            result.len() == 1,
            result[0].len() == arr.len(),
            forall |i: nat| 0 <= i < arr.len() ==> result[0][i] == arr[i],
    {
        let mut row: Vec<f32> = Vec::new();
        let n = arr.len() as nat;

        // Initialize the row with the same length as arr
        while row.len() < n
            invariant
                row.len() <= n,
                forall |i: nat| 0 <= i < row.len() ==> row[i] == arr[i],
            decreases n - row.len(),
        {
            row.push(arr[row.len()]);
        }

        // Return the two-dimensional array with one row
        vec![row]
    }
}

